<script setup>
import {ref,computed,watch,onMounted,onUnmounted} from 'vue'
import {resolveSceneUrl,acceptSceneMessage} from '../services/gantt-scene'
const props=defineProps({context:Object,allowedIds:{type:Array,default:()=>[]},src:{type:String,default:()=>import.meta.env.VITE_GANTT_IFRAME_URL||import.meta.env.VITE_COMMAND_IFRAME_URL||''}})
const emit=defineEmits(['close','select']),frame=ref(),reload=ref(0),state=ref('empty'),ready=ref(false)
const config=computed(()=>{try{return {endpoint:resolveSceneUrl(props.src,window.location.href)}}catch(e){return {error:e.message}}})
let timer
function start(){clearTimeout(timer);ready.value=false;state.value=config.value.endpoint?'loading':'empty';if(config.value.endpoint)timer=setTimeout(()=>state.value='timeout',15000)}
function send(){if(config.value.endpoint&&frame.value?.contentWindow&&['loaded','ready'].includes(state.value))frame.value.contentWindow.postMessage({type:'hospital:gantt-context',version:1,context:props.context},config.value.endpoint.origin)}
function loaded(){clearTimeout(timer);state.value='loaded';send()}
function retry(){reload.value++;start()}
function message(event){const packet=acceptSceneMessage(event,config.value.endpoint?.origin,frame.value?.contentWindow,props.allowedIds);if(!packet)return;if(packet.type==='hospital:scene-ready'){ready.value=true;state.value='ready';clearTimeout(timer);send()}else emit('select',packet.surgeryId)}
watch(()=>props.context,send,{deep:true});watch(()=>props.src,start)
onMounted(()=>{start();window.addEventListener('message',message)});onUnmounted(()=>{clearTimeout(timer);window.removeEventListener('message',message)})
</script>
<template><aside class="spatial-panel" aria-label="空间地图面板"><div class="panel-heading"><div><h2>空间地图</h2><span class="caption muted">{{ready?'联动就绪':config.endpoint?'iframe 接入位':'3D 待接入'}}</span></div><div class="inline-actions"><VBtn v-if="config.endpoint" icon="tabler-refresh" variant="text" color="secondary" size="small" aria-label="重新加载空间地图" @click="retry"/><VBtn icon="tabler-x" variant="text" color="secondary" size="small" aria-label="关闭空间地图" @click="emit('close')"/></div></div><div class="spatial-context"><strong>{{context?.operatingRoomNo||'全局空间'}}</strong><span>{{context?.surgeryId||'未选择手术'}} · {{context?.date}} {{context?.time}}</span></div><VProgressLinear v-if="state==='loading'" indeterminate/><div class="spatial-body"><div v-if="!config.endpoint||config.error" class="spatial-placeholder"><VIcon icon="tabler-building-hospital" size="42" color="primary"/><h3>空间地图待接入</h3><p>{{config.error||'预留 3D iframe，同步当前选中的手术、房间和复盘时点。'}}</p><dl v-if="context?.surgeryId"><dt>当前手术</dt><dd>{{context.surgeryId}}</dd><dt>手术间</dt><dd>{{context.operatingRoomNo||'—'}}</dd><dt>复盘时间</dt><dd>{{context.date}} {{context.time}}</dd></dl></div><template v-else><VAlert v-if="state==='timeout'||state==='error'" variant="tonal" type="warning" density="compact">场景暂未完成加载。<VBtn variant="text" size="small" @click="retry">重新加载</VBtn></VAlert><iframe ref="frame" :key="reload" :src="config.endpoint.url" title="甘特复盘联动空间地图" @load="loaded" @error="state='error'"/><p v-if="state==='loaded'&&!ready" class="scene-note caption muted">容器已加载，等待场景联动握手。</p></template></div></aside></template>
<style scoped>.spatial-panel{min-width:0;display:flex;flex-direction:column;height:100%;background:rgb(var(--v-theme-surface));border-inline-start:1px solid rgba(var(--v-border-color),var(--v-border-opacity))}.panel-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:12px 16px;border-bottom:1px solid rgba(var(--v-border-color),var(--v-border-opacity))}.panel-heading h2{font-size:16px;font-weight:600;line-height:24px}.panel-heading .inline-actions{gap:0}.spatial-context{display:flex;flex-direction:column;gap:4px;padding:10px 16px;background:rgba(var(--v-theme-on-surface),.025);font-size:12px;line-height:20px;overflow-wrap:anywhere}.spatial-context strong{font-size:14px;font-weight:500}.spatial-body{flex:1;min-height:0;display:flex;flex-direction:column;position:relative}.spatial-body iframe{width:100%;flex:1;min-height:300px;border:0;background:rgb(var(--v-theme-background))}.spatial-placeholder{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:16px;text-align:center;padding:24px 18px;flex:1}.spatial-placeholder h3{font-size:16px;font-weight:500}.spatial-placeholder p{font-size:14px;line-height:22px;color:rgba(var(--v-theme-on-surface),.6)}.spatial-placeholder dl{text-align:start;align-self:stretch;font-size:12px;line-height:20px;border:1px solid rgba(var(--v-border-color),var(--v-border-opacity));border-radius:6px;padding:14px}.spatial-placeholder dt{color:rgba(var(--v-theme-on-surface),.6);margin-top:8px}.spatial-placeholder dt:first-child{margin-top:0}.spatial-placeholder dd{margin:2px 0 0;overflow-wrap:anywhere}.scene-note{padding:8px 12px}</style>
